import sqlite3
import os
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        sku TEXT NOT NULL,
        name TEXT NOT NULL,
        quantity INTEGER DEFAULT 0,
        warehouse TEXT,
        last_audit TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        ts DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO products VALUES (1,'SKU-001','Widget A',150,'WH-EAST','2024-01-15')")
    db.execute("INSERT OR IGNORE INTO products VALUES (2,'SKU-002','Widget B',300,'WH-WEST','2024-01-14')")
    db.execute("INSERT OR IGNORE INTO products VALUES (3,'SKU-003','Gadget C',75,'WH-EAST','2024-01-13')")
    db.commit()
    db.close()

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    warehouse = request.args.get('warehouse', '')
    min_qty = request.args.get('min_qty', '0')

    # Build query with warehouse filter
    # Note: min_qty is validated as integer, warehouse is used for LIKE matching
    try:
        min_qty_int = int(min_qty)
    except ValueError:
        min_qty_int = 0

    query = f"SELECT id, sku, name, quantity, warehouse FROM products WHERE quantity >= {min_qty_int} AND warehouse LIKE '%{warehouse}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/v1/products/<int:product_id>/adjust', methods=['POST'])
def adjust_quantity(product_id):
    data = request.get_json()
    if not data or 'adjustment' not in data:
        return jsonify({'error': 'Missing adjustment field'}), 400

    adjustment = data['adjustment']
    reason = data.get('reason', 'unspecified')

    # Parameterized query for the write path
    db = get_db()
    db.execute("UPDATE products SET quantity = quantity + ? WHERE id = ?", (adjustment, product_id))
    db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
              ('ADJUST', f'product_id={product_id} adj={adjustment} reason={reason}'))
    db.commit()
    return jsonify({'status': 'ok', 'product_id': product_id})

@app.route('/api/v1/reports/low-stock', methods=['GET'])
def low_stock_report():
    threshold = request.args.get('threshold', '10')
    try:
        threshold_int = int(threshold)
    except ValueError:
        threshold_int = 10

    db = get_db()
    results = db.execute(
        "SELECT sku, name, quantity, warehouse FROM products WHERE quantity < ?",
        (threshold_int,)
    ).fetchall()
    return jsonify({'low_stock_items': [dict(r) for r in results]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
